OLD = '/work/shares/old-nas'
TEAM = '/work/shares/team'
MODE = sys.argv[1] if len(sys.argv) > 1 else 'plan'


def kind(p):
    if os.path.islink(p):
        return 'l'
    if os.path.isdir(p):
        return 'd'
    if os.path.isfile(p):
        return 'f'
    return None


def sha(p):
    h = hashlib.sha256()
    with open(p, 'rb') as f:
        for chunk in iter(lambda: f.read(1 << 20), b''):
            h.update(chunk)
    return h.hexdigest()


def inside(path, base):
    return path == base or path.startswith(base + '/')


def renamed(rel):
    d, name = os.path.split(rel)
    idx = name.rfind('.')
    if idx > 0:
        stem, ext = name[:idx], name[idx:]
    else:
        stem, ext = name, ''
    new = f'{stem} (old-nas){ext}'
    return os.path.join(d, new) if d else new


# ---- enumerate old-nas (everything, including hidden and empty dirs, links)
old = []
for root, dirs, files in os.walk(OLD):
    for n in dirs + files:
        full = os.path.join(root, n)
        old.append((os.path.relpath(full, OLD), kind(full)))
old.sort()

dest = {}      # old rel -> team rel, or None when team copy is kept (dedupe)
notes = []
planned = set()
for rel, k in old:
    tp = os.path.join(TEAM, rel)
    tk = kind(tp)
    if k == 'd':
        if tk in (None, 'd'):
            dest[rel] = rel
        else:
            notes.append(f'CONFLICT dir vs {tk}: {rel}')
            dest[rel] = rel
        continue
    if tk is None:
        dest[rel] = rel
    elif k == 'f' and tk == 'f' and sha(tp) == sha(os.path.join(OLD, rel)):
        dest[rel] = None
        notes.append(f'DEDUPE {rel}')
    else:
        nr = renamed(rel)
        if kind(os.path.join(TEAM, nr)) is not None or nr in planned or nr in dest:
            notes.append(f'CONFLICT rename target exists: {nr}')
        dest[rel] = nr
        notes.append(f'RENAME [{k} vs team {tk}] {rel} -> {nr}')
    if dest[rel] is not None:
        planned.add(dest[rel])

# ---- link target computation
def map_abs(a):
    """map an absolute path inside old-nas to its team path, else None"""
    if not inside(a, OLD):
        return None
    sub = os.path.relpath(a, OLD)
    d = dest.get(sub, sub)
    if d is None:
        d = sub
    return os.path.normpath(os.path.join(TEAM, d))


link_changes = []  # (new_link_path, old_link_path, old_target, new_target, action)
for rel, k in old:
    if k != 'l':
        continue
    lp_old = os.path.join(OLD, rel)
    t = os.readlink(lp_old)
    a = os.path.normpath(t if os.path.isabs(t) else os.path.join(os.path.dirname(lp_old), t))
    d = dest[rel]
    if d is None:
        notes.append(f'ERROR link deduped {rel}')
        continue
    lp_new = os.path.join(TEAM, d)
    mapped = map_abs(a)
    if mapped is None:
        target_abs = a
    else:
        target_abs = mapped
    if os.path.isabs(t) and mapped is None:
        new_t = t
    elif os.path.isabs(t):
        new_t = target_abs
    else:
        new_t = os.path.relpath(target_abs, os.path.dirname(lp_new))
    link_changes.append((lp_new, lp_old, t, new_t))

# links already in team that point into old-nas
team_fix = []
for root, dirs, files in os.walk(TEAM):
    for n in dirs + files:
        full = os.path.join(root, n)
        if os.path.islink(full):
            t = os.readlink(full)
            a = os.path.normpath(t if os.path.isabs(t) else os.path.join(root, t))
            if inside(a, OLD):
                mapped = map_abs(a)
                new_t = mapped if os.path.isabs(t) else os.path.relpath(mapped, root)
                team_fix.append((full, t, new_t))

if MODE == 'plan':
    from collections import Counter
    print('old entries', len(old), Counter(k for _, k in old))
    for n in notes:
        print(n)
    print('LINKS in old-nas:')
    for lp_new, lp_old, t, nt in link_changes:
        print(' ', os.path.relpath(lp_old, OLD), '|', t, '=>', nt, '| at', os.path.relpath(lp_new, TEAM))
    print('LINKS in team into old-nas:')
    for full, t, nt in team_fix:
        print(' ', os.path.relpath(full, TEAM), '|', t, '=>', nt)
    sys.exit(0)
